import React from "react";
import { motion } from "framer-motion";
import { partners } from "../../data/content";
import AnimatedSection from "../ui/AnimatedSection";

export default function Partners() {
  const doubled = [...partners, ...partners];

  return (
    <section
      id="partners"
      className="bg-charcoal-900 section-pad overflow-hidden"
    >
      <div className="max-w-7xl mx-auto px-6 lg:px-10 mb-14">
        <div className="flex flex-col lg:flex-row lg:items-end justify-between gap-6">
          <div>
            <AnimatedSection variant="fadeUp">
              <span className="eyebrow text-white/35 mb-4 block">
                Technology Partners
              </span>
            </AnimatedSection>

            <AnimatedSection variant="fadeUp" delay={0.1}>
              <h2 className="font-display text-[clamp(2.2rem,4vw,3.2rem)] text-white leading-[1.12]">
                Global Technology Partners.{" "}
                <em className="text-[#0F2A56] not-italic">
                  Trusted Infrastructure Delivery.
                </em>
              </h2>
            </AnimatedSection>
          </div>

          <AnimatedSection
            variant="fadeUp"
            delay={0.2}
            className="max-w-md"
          >
            <p className="text-white/40 text-sm leading-relaxed">
              Baylem partners with globally recognised manufacturers of medical
              and non-medical cold chain systems, pathology laboratories,
              mortuary equipment, and healthcare infrastructure technologies
              across Kenya and East Africa.
            </p>
          </AnimatedSection>
        </div>
      </div>

      {/* Row 1 */}
      <div className="relative mb-3">
        <div className="absolute left-0 top-0 bottom-0 w-24 bg-gradient-to-r from-charcoal-900 to-transparent z-10 pointer-events-none" />
        <div className="absolute right-0 top-0 bottom-0 w-24 bg-gradient-to-l from-charcoal-900 to-transparent z-10 pointer-events-none" />

        <motion.div
          className="flex gap-3"
          animate={{ x: ["0%", "-50%"] }}
          transition={{
            duration: 28,
            repeat: Infinity,
            ease: "linear",
          }}
        >
          {doubled.map((partner, index) => (
            <PartnerTile
              key={`${partner.id}-${index}`}
              partner={partner}
            />
          ))}
        </motion.div>
      </div>

      {/* Row 2 */}
      <div className="relative">
        <div className="absolute left-0 top-0 bottom-0 w-24 bg-gradient-to-r from-charcoal-900 to-transparent z-10 pointer-events-none" />
        <div className="absolute right-0 top-0 bottom-0 w-24 bg-gradient-to-l from-charcoal-900 to-transparent z-10 pointer-events-none" />

        <motion.div
          className="flex gap-3"
          animate={{ x: ["-50%", "0%"] }}
          transition={{
            duration: 32,
            repeat: Infinity,
            ease: "linear",
          }}
        >
          {doubled.map((partner, index) => (
            <PartnerTile
              key={`reverse-${partner.id}-${index}`}
              partner={partner}
              dim
            />
          ))}
        </motion.div>
      </div>

      {/* Bottom note */}
      <AnimatedSection
        variant="fadeUp"
        delay={0.3}
        className="max-w-7xl mx-auto px-6 lg:px-10 mt-14"
      >
        <div className="flex flex-col md:flex-row items-center justify-between gap-4 pt-10 border-t border-white/10">
          <p className="text-white/30 text-[12.5px]">
            Authorised distributor, systems integrator, and fabrication partner
            serving healthcare, research, industrial, and public sector clients
            across Kenya and East Africa.
          </p>

          <motion.button
            whileHover={{ scale: 1.03 }}
            whileTap={{ scale: 0.97 }}
            onClick={() =>
              document
                .getElementById("contact")
                ?.scrollIntoView({ behavior: "smooth" })
            }
            className="text-[#0F2A56] text-[13px] font-bold tracking-wide hover:text-blue-300 transition-colors"
          >
            Enquire about a specific brand →
          </motion.button>
        </div>
      </AnimatedSection>
    </section>
  );
}

function PartnerTile({ partner, dim = false }) {
  const isFabrication = partner.name === "Baylem Fabrication";

  return (
    <motion.div
      whileHover={{
        scale: 1.04,
        backgroundColor: "#1e2d47",
      }}
      transition={{ duration: 0.2 }}
      className={`flex-shrink-0 bg-charcoal-800 border border-white/8 rounded-xl px-8 py-5 flex items-center justify-center min-w-[220px] h-[120px] ${
        dim ? "opacity-60" : ""
      }`}
    >
      {isFabrication ? (
        <div className="flex flex-col items-center">
          <div className="w-14 h-14 rounded-xl bg-[#0F2A56] flex items-center justify-center">
            <span className="text-white font-black text-xl">B</span>
          </div>

          <span className="mt-3 text-white font-semibold text-sm">
            BAYLEM FABRICATION
          </span>

          <span className="text-white/40 text-xs">
            Custom Cold Chain & Morgue Systems
          </span>
        </div>
      ) : (
        <img
          src={require(`../../assets/images/partners/${partner.logo}`)}
          alt={partner.name}
          className="
            max-h-12
            w-auto
            object-contain
            grayscale
            opacity-80
            hover:opacity-100
            hover:grayscale-0
            transition-all
            duration-300
          "
        />
      )}
    </motion.div>
  );
}
